def transform(g):
    h,w=len(g),len(g[0])
    from collections import Counter
    c=Counter(x for r in g for x in r)
    bg=c.most_common(1)[0][0]
    fgset=set(c)-{bg}
    out=[r[:] for r in g]
    for i in range(h):
        fg=[j for j in range(w) if g[i][j] in fgset]
        for j in range(w):
            if g[i][j]==bg and any(f<j for f in fg) and any(f>j for f in fg):
                out[i][j]=3
    for j in range(w):
        fg=[i for i in range(h) if g[i][j] in fgset]
        for i in range(h):
            if g[i][j]==bg and any(f<i for f in fg) and any(f>i for f in fg):
                out[i][j]=3
    return out
